704	        // cargo test captures stdout. prompt_yes_no detects non-TTY via
705	        // read_key() and returns an IO error — no SIGTTOU, no panic.
706	        let term = Term::stdout();
707	        if term.is_term() {
708	            return; // Skip under --nocapture with real TTY
709	        }
710	
711	        let options = vec![
712	            PromptOption {
713	                label: "Yes (y)".to_string(),
714	                value: "yes".to_string(),
715	            },
716	            PromptOption {
717	                label: "No (n)".to_string(),
718	                value: "no".to_string(),
719	            },
