86	impl Prompter for NonInteractiveUI {
87	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
88	        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
89	
90	        // Check environment override (KEY=value, e.g. BUMP=minor).
91	        // This is handled by prompt_user for TerminalUI, but
92	        // NonInteractiveUI doesn't call prompt_user, so check here too.
93	        if let Some(result) = super::prompts::env_override(prompt) {
94	            return Ok(result);
95	        }
96	
97	        // Use default
98	        if let Some(default) = &prompt.default {
99	            if is_multiselect {
100	                let values: Vec<String> =
101	                    default.split(',').map(|s| s.trim().to_string()).collect();
102	                return Ok(PromptResult::Strings(values));
103	            }
104	            return Ok(PromptResult::String(default.clone()));
105	        }
106	
107	        Err(BivvyError::ConfigValidationError {
108	            message: format!(
109	                "Cannot prompt for '{}' in non-interactive mode (no default value)",
110	                prompt.key
111	            ),
112	        })
113	    }
114	}
