172	    /// Execute `--template`: generate config from a specific template or category.
173	    fn execute_template(
174	        &self,
175	        ui: &mut dyn UserInterface,
176	        template_name: &str,
177	    ) -> Result<CommandResult> {
178	        let loader = match BuiltinLoader::new() {
179	            Ok(l) => l,
180	            Err(e) => {
181	                ui.error(&format!("Failed to load templates: {}", e));
182	                return Ok(CommandResult::failure(1));
183	            }
184	        };
185	
186	        // Collect matching templates: first try as a direct template name,
187	        // then try as a category name to find all templates in that category.
188	        let mut steps: Vec<(String, Option<&Template>)> = Vec::new();
189	
190	        if let Some(tmpl) = loader.get(template_name) {
191	            // Direct template match
192	            steps.push((tmpl.name.clone(), Some(tmpl)));
193	        } else {
194	            // Try as a category — find all templates in this category
195	            for qualified_name in loader.template_names() {
196	                if let Some(tmpl) = loader.get(qualified_name) {
197	                    if tmpl.category == template_name {
198	                        steps.push((tmpl.name.clone(), Some(tmpl)));
199	                    }
200	                }
201	            }
202	        }
203	
204	        if steps.is_empty() {
205	            ui.error(&format!(
206	                "No template or category found matching '{}'",
207	                template_name
208	            ));
209	            ui.message("Run 'bivvy templates' to see available templates.");
210	            return Ok(CommandResult::failure(1));
211	        }
212	
213	        ui.message(&format!("Using template: {}", template_name));
214	
215	        let steps_with_templates: Vec<(&str, Option<&Template>)> = steps
216	            .iter()
217	            .map(|(name, tmpl)| (name.as_str(), *tmpl))
218	            .collect();
219	
220	        let schema = Self::schema_path();
221	        let config = self.create_config(&steps_with_templates, schema.as_deref());
222	
223	        let bivvy_dir = self.project_root.join(".bivvy");
224	        fs::create_dir_all(&bivvy_dir)?;
225	        fs::write(bivvy_dir.join("config.yml"), &config)?;
226	
227	        self.update_gitignore(ui)?;
228	
229	        ui.message("");
230	        ui.success("Created .bivvy/config.yml");
231	
232	        let step_names: Vec<&str> = steps.iter().map(|(n, _)| n.as_str()).collect();
233	        ui.message("Workflow: default");
234	        ui.message(&format!(
235	            "Steps: {} ({})",
236	            steps.len(),
237	            step_names.join(", ")
238	        ));
239	        ui.message("");
240	
241	        ui.show_hint(hints::after_init());
242	        Ok(CommandResult::success())
243	    }
244	
245	    /// Update gitignore to exclude local overrides.
246	    ///
247	    /// Only requires `OutputWriter` — displays a message but does not prompt.
248	    fn update_gitignore(&self, ui: &mut dyn OutputWriter) -> Result<()> {
249	        let entries = [".bivvy/config.local.yml"];
250	        let gitignore_path = self.project_root.join(".gitignore");
251	
252	        if gitignore_path.exists() {
253	            let content = fs::read_to_string(&gitignore_path)?;
254	            let mut new_content = content.clone();
255	
256	            for entry in &entries {
257	                if !new_content.contains(entry) {
258	                    if !new_content.ends_with('\n') {
259	                        new_content.push('\n');
260	                    }
261	                    new_content.push_str(entry);
262	                    new_content.push('\n');
263	                    ui.message(&format!("Added {} to .gitignore", entry));
264	                }
265	            }
266	
267	            if new_content != content {
268	                fs::write(&gitignore_path, new_content)?;
269	            }
270	        }
271	
272	        Ok(())
273	    }
274	}
