1	//! Remote configuration fetching.
2	//!
3	//! This module provides functionality for fetching configuration files
4	//! from remote URLs.
5	
6	use anyhow::{anyhow, Context, Result};
7	use std::collections::HashMap;
8	use std::path::PathBuf;
9	use std::time::Duration;
10	
11	/// Fetches remote configuration files with caching.
12	///
13	/// # Example
14	///
15	/// ```no_run
16	/// use bivvy::config::RemoteFetcher;
17	/// use std::time::Duration;
18	///
19	/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
20	///
21	/// // Fetch a remote config file
22	/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
23	/// ```
24	pub struct RemoteFetcher {
25	    /// Request timeout.
26	    timeout: Duration,
27	    /// Cache directory for downloaded configs.
28	    cache_dir: PathBuf,
29	    /// HTTP client.
30	    client: reqwest::blocking::Client,
31	}
32	
33	impl RemoteFetcher {
34	    /// Create a fetcher with the specified timeout.
35	    pub fn new(timeout: Duration) -> Self {
36	        let cache_dir = crate::sys::cache_dir()
37	            .unwrap_or_else(|| PathBuf::from("~/.cache"))
38	            .join("bivvy")
39	            .join("remote-configs");
40	
41	        Self {
42	            timeout,
43	            cache_dir,
44	            client: reqwest::blocking::Client::builder()
45	                .timeout(timeout)
46	                .build()
47	                .expect("Failed to create HTTP client"),
48	        }
49	    }
50	
51	    /// Create a fetcher with a custom cache directory.
52	    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
53	        Self {
54	            timeout,
55	            cache_dir,
56	            client: reqwest::blocking::Client::builder()
57	                .timeout(timeout)
58	                .build()
59	                .expect("Failed to create HTTP client"),
60	        }
61	    }
62	
63	    /// Fetch a configuration file from a URL.
64	    pub fn fetch(&self, url: &str) -> Result<String> {
65	        // Check cache first
66	        if let Some(cached) = self.check_cache(url)? {
67	            return Ok(cached);
68	        }
69	
70	        // Fetch from remote
71	        let content = self.fetch_remote(url)?;
72	
73	        // Cache the result
74	        self.save_cache(url, &content)?;
75	
76	        Ok(content)
77	    }
78	
79	    /// Fetch a configuration file, bypassing cache.
80	    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
81	        self.fetch_remote(url)
82	    }
83	
84	    /// Fetch with authentication header.
85	    ///
86	    /// Requires HTTPS to prevent credential leakage over plain HTTP.
87	    /// Returns an error if the URL scheme is not `https://`.
88	    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
89	        if !url.starts_with("https://") {
90	            return Err(anyhow!(
91	                "Refusing to send auth headers over insecure HTTP: {}. Use HTTPS instead",
92	                url
93	            ));
94	        }
95	
96	        let response = self
97	            .client
98	            .get(url)
99	            .header(&auth.header_name, &auth.header_value)
100	            .send()
101	            .with_context(|| format!("Failed to fetch {}", url))?;
102	
103	        if !response.status().is_success() {
104	            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
105	        }
106	
107	        response
108	            .text()
109	            .with_context(|| format!("Failed to read response from {}", url))
110	    }
111	
112	    fn fetch_remote(&self, url: &str) -> Result<String> {
113	        let response = self
114	            .client
115	            .get(url)
116	            .send()
117	            .with_context(|| format!("Failed to fetch {}", url))?;
118	
119	        if !response.status().is_success() {
120	            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
121	        }
122	
123	        response
124	            .text()
125	            .with_context(|| format!("Failed to read response from {}", url))
126	    }
127	
128	    fn check_cache(&self, url: &str) -> Result<Option<String>> {
129	        let cache_path = self.cache_path(url);
130	        if cache_path.exists() {
131	            let content = std::fs::read_to_string(&cache_path)?;
132	            Ok(Some(content))
133	        } else {
134	            Ok(None)
135	        }
136	    }
137	
138	    fn save_cache(&self, url: &str, content: &str) -> Result<()> {
139	        let cache_path = self.cache_path(url);
140	        if let Some(parent) = cache_path.parent() {
141	            std::fs::create_dir_all(parent)?;
142	        }
143	        std::fs::write(&cache_path, content)?;
144	        Ok(())
145	    }
146	
147	    fn cache_path(&self, url: &str) -> PathBuf {
148	        use sha2::{Digest, Sha256};
149	        let mut hasher = Sha256::new();
150	        hasher.update(url.as_bytes());
151	        let hash = hex::encode(hasher.finalize());
152	        self.cache_dir.join(format!("{}.yml", hash))
153	    }
154	
155	    /// Clear the cache for a specific URL.
156	    pub fn clear_cache(&self, url: &str) -> Result<()> {
157	        let cache_path = self.cache_path(url);
158	        if cache_path.exists() {
159	            std::fs::remove_file(&cache_path)?;
160	        }
161	        Ok(())
162	    }
163	
164	    /// Clear all cached configurations.
165	    pub fn clear_all_cache(&self) -> Result<()> {
166	        if self.cache_dir.exists() {
167	            std::fs::remove_dir_all(&self.cache_dir)?;
168	        }
169	        Ok(())
170	    }
171	
172	    /// Get the request timeout.
173	    pub fn timeout(&self) -> Duration {
174	        self.timeout
175	    }
176	}
177	
178	impl Default for RemoteFetcher {
179	    fn default() -> Self {
180	        Self::new(Duration::from_secs(30))
181	    }
182	}
183	
184	/// Authentication header for remote fetching.
185	#[derive(Debug, Clone)]
186	pub struct AuthHeader {
187	    /// Header name (e.g., "Authorization").
188	    pub header_name: String,
189	    /// Header value (e.g., "Bearer token123").
190	    pub header_value: String,
191	}
192	
193	impl AuthHeader {
194	    /// Create a Bearer token auth header.
195	    pub fn bearer(token: &str) -> Self {
196	        Self {
197	            header_name: "Authorization".to_string(),
198	            header_value: format!("Bearer {}", token),
199	        }
200	    }
201	
202	    /// Create a custom header auth.
203	    pub fn custom(name: impl Into<String>, value: impl Into<String>) -> Self {
204	        Self {
205	            header_name: name.into(),
206	            header_value: value.into(),
207	        }
208	    }
209	}
210	
211	/// Resolves authentication from config settings.
212	pub fn resolve_auth(
213	    auth_type: &str,
214	    token_env: &str,
215	    header: Option<&str>,
216	    env_vars: &HashMap<String, String>,
217	) -> Option<AuthHeader> {
218	    // First check the provided env_vars map, then fall back to system env
219	    let token = env_vars
220	        .get(token_env)
221	        .cloned()
222	        .or_else(|| std::env::var(token_env).ok())?;
223	
224	    match auth_type {
225	        "bearer" => Some(AuthHeader::bearer(&token)),
226	        "header" => {
227	            let header_name = header.unwrap_or("X-Auth-Token");
228	            Some(AuthHeader::custom(header_name, &token))
229	        }
230	        _ => None,
231	    }
232	}
233	
234	#[cfg(test)]
235	mod tests {
236	    use super::*;
237	    use httpmock::prelude::*;
238	    use tempfile::TempDir;
239	
240	    #[test]
241	    fn creates_fetcher_with_default_timeout() {
242	        let fetcher = RemoteFetcher::default();
243	        assert_eq!(fetcher.timeout(), Duration::from_secs(30));
244	    }
245	
246	    #[test]
247	    fn creates_fetcher_with_custom_timeout() {
248	        let fetcher = RemoteFetcher::new(Duration::from_secs(60));
249	        assert_eq!(fetcher.timeout(), Duration::from_secs(60));
250	    }
251	
252	    #[test]
253	    fn creates_fetcher_with_custom_cache_dir() {
254	        let temp = TempDir::new().unwrap();
255	        let fetcher =
256	            RemoteFetcher::with_cache_dir(Duration::from_secs(30), temp.path().join("cache"));
257	        assert!(fetcher.cache_dir.ends_with("cache"));
258	    }
259	
260	    #[test]
261	    fn bearer_auth_header_format() {
262	        let auth = AuthHeader::bearer("my-token");
263	        assert_eq!(auth.header_name, "Authorization");
264	        assert_eq!(auth.header_value, "Bearer my-token");
265	    }
266	
267	    #[test]
268	    fn custom_auth_header_format() {
269	        let auth = AuthHeader::custom("X-API-Key", "secret123");
270	        assert_eq!(auth.header_name, "X-API-Key");
271	        assert_eq!(auth.header_value, "secret123");
272	    }
273	
274	    #[test]
275	    fn resolve_auth_bearer() {
276	        let mut env = HashMap::new();
277	        env.insert("MY_TOKEN".to_string(), "token-value".to_string());
278	
279	        let auth = resolve_auth("bearer", "MY_TOKEN", None, &env);
280	
281	        assert!(auth.is_some());
282	        let auth = auth.unwrap();
283	        assert_eq!(auth.header_value, "Bearer token-value");
284	    }
285	
286	    #[test]
287	    fn resolve_auth_custom_header() {
288	        let mut env = HashMap::new();
289	        env.insert("API_KEY".to_string(), "key-value".to_string());
290	
291	        let auth = resolve_auth("header", "API_KEY", Some("X-API-Key"), &env);
292	
293	        assert!(auth.is_some());
294	        let auth = auth.unwrap();
295	        assert_eq!(auth.header_name, "X-API-Key");
296	        assert_eq!(auth.header_value, "key-value");
297	    }
298	
299	    #[test]
300	    fn resolve_auth_missing_env_var() {
301	        let env = HashMap::new();
302	        // Remove the env var if it exists
303	        std::env::remove_var("NONEXISTENT_VAR");
304	
305	        let auth = resolve_auth("bearer", "NONEXISTENT_VAR", None, &env);
306	
307	        assert!(auth.is_none());
308	    }
309	
310	    #[test]
311	    fn cache_path_is_deterministic() {
312	        let temp = TempDir::new().unwrap();
313	        let fetcher =
314	            RemoteFetcher::with_cache_dir(Duration::from_secs(30), temp.path().to_path_buf());
315	
316	        let path1 = fetcher.cache_path("https://example.com/config.yml");
317	        let path2 = fetcher.cache_path("https://example.com/config.yml");
318	
319	        assert_eq!(path1, path2);
320	    }
321	
322	    #[test]
323	    fn different_urls_have_different_cache_paths() {
324	        let temp = TempDir::new().unwrap();
325	        let fetcher =
326	            RemoteFetcher::with_cache_dir(Duration::from_secs(30), temp.path().to_path_buf());
327	
328	        let path1 = fetcher.cache_path("https://example.com/config1.yml");
329	        let path2 = fetcher.cache_path("https://example.com/config2.yml");
330	
331	        assert_ne!(path1, path2);
332	    }
333	
334	    #[test]
335	    fn clear_cache_removes_cached_file() {
336	        let temp = TempDir::new().unwrap();
337	        let fetcher =
338	            RemoteFetcher::with_cache_dir(Duration::from_secs(30), temp.path().to_path_buf());
339	
340	        let url = "https://example.com/test.yml";
341	        let cache_path = fetcher.cache_path(url);
342	
343	        // Create a cached file
344	        std::fs::create_dir_all(cache_path.parent().unwrap()).unwrap();
345	        std::fs::write(&cache_path, "test content").unwrap();
346	        assert!(cache_path.exists());
347	
348	        // Clear it
349	        fetcher.clear_cache(url).unwrap();
350	        assert!(!cache_path.exists());
351	    }
352	
353	    #[test]
354	    fn clear_all_cache_removes_directory() {
355	        let temp = TempDir::new().unwrap();
356	        let cache_dir = temp.path().join("cache");
357	        let fetcher = RemoteFetcher::with_cache_dir(Duration::from_secs(30), cache_dir.clone());
358	
359	        // Create some cached files
360	        std::fs::create_dir_all(&cache_dir).unwrap();
361	        std::fs::write(cache_dir.join("file1.yml"), "content").unwrap();
362	        std::fs::write(cache_dir.join("file2.yml"), "content").unwrap();
363	
364	        assert!(cache_dir.exists());
365	
366	        // Clear all
367	        fetcher.clear_all_cache().unwrap();
368	        assert!(!cache_dir.exists());
369	    }
370	
371	    // --- Mock HTTP tests ---
372	
