654	    #[test]
655	    fn select_theme_creates_without_panic() {
656	        let theme = select_theme();
657	        // Verify the theme object can be used (smoke test)
658	        drop(theme);
659	    }
660	
661	    #[test]
662	    fn cursor_guard_restores_on_drop() {
663	        // CursorGuard::new requires a real terminal for hide_cursor(),
664	        // but we can verify the struct compiles and the Drop impl exists
665	        // by constructing with Term::stdout() in a non-panicking context.
666	        // On non-TTY (CI), hide_cursor is a no-op that still succeeds.
667	        let term = Term::stdout();
