+    fn ctrl_d_in_yes_no_selects_no() {
+        // Ctrl+D (EOT, byte 0x04) in raw mode should behave like Escape:
+        // gracefully select "no" (or the default) rather than looping
+        // forever or panicking.
+        let term = Term::stdout();
+        if term.is_term() {
+            return; // Cannot simulate keystrokes on a real TTY in unit tests
+        }
+
+        let options = vec![
+            PromptOption {
+                label: "Yes (y)".to_string(),
+                value: "yes".to_string(),
+            },
+            PromptOption {
+                label: "No (n)".to_string(),
+                value: "no".to_string(),
+            },
+        ];
+        let prompt = make_prompt(
+            "confirm_step",
+            PromptType::Select {
+                options: options.clone(),
+            },
+            Some("yes"),
+        );
+
+        // On a non-TTY, read_key() returns an IO error (EOF) immediately.
+        // The prompt should convert this to a graceful error, not panic.
+        let result = prompt_yes_no(&prompt, &options, &term);
+        // Must not panic — an Err is acceptable (IO error from non-TTY).
+        assert!(result.is_err());
+    }
